CREATE TABLE "Author" ("id" SERIAL NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Author_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Post" ("id" SERIAL NOT NULL,"title" TEXT NOT NULL,"body" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'published',"authorId" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Post_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Comment" ("id" SERIAL NOT NULL,"body" TEXT NOT NULL,"postId" INTEGER NOT NULL,"authorId" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Comment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Tag" ("id" SERIAL NOT NULL,"name" TEXT NOT NULL,CONSTRAINT "Tag_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PostTag" ("postId" INTEGER NOT NULL,"tagId" INTEGER NOT NULL,CONSTRAINT "PostTag_pkey" PRIMARY KEY ("postId","tagId"));
CREATE UNIQUE INDEX "Author_email_key" ON "Author"("email"); CREATE UNIQUE INDEX "Tag_name_key" ON "Tag"("name"); CREATE INDEX "Post_createdAt_idx" ON "Post"("createdAt"); CREATE INDEX "Post_authorId_idx" ON "Post"("authorId"); CREATE INDEX "Comment_postId_idx" ON "Comment"("postId");
ALTER TABLE "Post" ADD CONSTRAINT "Post_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "Author"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Comment" ADD CONSTRAINT "Comment_authorId_fkey" FOREIGN KEY ("authorId") REFERENCES "Author"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "PostTag" ADD CONSTRAINT "PostTag_postId_fkey" FOREIGN KEY ("postId") REFERENCES "Post"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PostTag" ADD CONSTRAINT "PostTag_tagId_fkey" FOREIGN KEY ("tagId") REFERENCES "Tag"("id") ON DELETE CASCADE ON UPDATE CASCADE;
